#!/usr/bin/env python3
"""Merge user data from JSON, CSV and Parquet sources.

Priority: source_a > source_b > source_c.
"""

from __future__ import annotations

import json
from datetime import date, datetime
from pathlib import Path
from typing import Any

import pandas as pd

BASE = Path("/data")
OUT_DIR = Path("/app")

# Canonical field -> possible source column names.
FIELD_ALIASES: dict[str, list[str]] = {
    "user_id": ["user_id", "id", "userId"],
    "name": ["full_name", "name", "userName"],
    "email": ["email", "email_address"],
    "created_date": ["registration_date", "created_at", "joined"],
    "status": ["status", "is_active", "active"],
}

# The four explicitly required fields (status is optional).
OUTPUT_FIELDS = ["name", "email", "created_date", "status"]


def is_missing(value: Any) -> bool:
    if value is None:
        return True
    try:
        return bool(pd.isna(value))
    except (TypeError, ValueError):
        return False


def normalize_user_id(value: Any) -> int:
    if isinstance(value, bool):
        return int(value)
    if isinstance(value, float) and value.is_integer():
        return int(value)
    return int(value)


def normalize_date(value: Any) -> str:
    if isinstance(value, (pd.Timestamp, datetime, date)):
        return pd.Timestamp(value).strftime("%Y-%m-%d")

    text = str(value).strip()
    # Parse common date/datetime representations and emit YYYY-MM-DD.
    parsed = pd.to_datetime(text, errors="coerce")
    if not pd.isna(parsed):
        return parsed.strftime("%Y-%m-%d")
    return text


def normalize_status(value: Any) -> str:
    if isinstance(value, bool):
        return "active" if value else "inactive"

    if isinstance(value, (int, float)) and not isinstance(value, bool):
        if value == 1:
            return "active"
        if value == 0:
            return "inactive"

    text = str(value).strip()
    lowered = text.lower()
    if lowered in {"true", "1", "yes", "active"}:
        return "active"
    if lowered in {"false", "0", "no", "inactive"}:
        return "inactive"
    return text


def normalize_value(field: str, value: Any) -> Any:
    if field == "user_id":
        return normalize_user_id(value)
    if field == "created_date":
        return normalize_date(value)
    if field == "status":
        return normalize_status(value)
    return str(value).strip()


def first_present(record: dict[str, Any], aliases: list[str]) -> Any:
    for alias in aliases:
        if alias in record and not is_missing(record[alias]):
            return record[alias]
    return None


def load_source(name: str, path: Path) -> pd.DataFrame:
    if path.suffix.lower() == ".json":
        with path.open("r", encoding="utf-8") as fh:
            data = json.load(fh)
        return pd.DataFrame(data)
    if path.suffix.lower() == ".csv":
        return pd.read_csv(path)
    if path.suffix.lower() == ".parquet":
        return pd.read_parquet(path)
    raise ValueError(f"Unsupported source format: {path}")


def main() -> None:
    source_paths = {
        "source_a": BASE / "source_a" / "users.json",
        "source_b": BASE / "source_b" / "users.csv",
        "source_c": BASE / "source_c" / "users.parquet",
    }
    priority = ["source_a", "source_b", "source_c"]

    # collected[user_id][field][source] = normalized value
    collected: dict[int, dict[str, dict[str, Any]]] = {}

    for source_name in priority:
        df = load_source(source_name, source_paths[source_name])
        for record in df.to_dict(orient="records"):
            raw_id = first_present(record, FIELD_ALIASES["user_id"])
            if raw_id is None:
                continue
            user_id = normalize_value("user_id", raw_id)

            user_fields = collected.setdefault(user_id, {})
            for field in OUTPUT_FIELDS:
                raw_value = first_present(record, FIELD_ALIASES[field])
                if raw_value is None:
                    continue
                value = normalize_value(field, raw_value)
                if field == "status" and value == "":
                    continue
                user_fields.setdefault(field, {})[source_name] = value

    merged_rows: list[dict[str, Any]] = []
    conflicts: list[dict[str, Any]] = []

    for user_id in sorted(collected):
        fields = collected[user_id]
        row: dict[str, Any] = {"user_id": user_id}

        for field in OUTPUT_FIELDS:
            values_by_source = fields.get(field, {})
            present_values = [
                values_by_source[source]
                for source in priority
                if source in values_by_source
            ]

            # Highest-priority source supplies the selected value.
            selected = present_values[0] if present_values else None
            row[field] = selected

            # A conflict exists when multiple sources carry different values.
            if len({str(v) for v in present_values}) > 1:
                conflicts.append(
                    {
                        "user_id": user_id,
                        "field": field,
                        "values": {
                            source: values_by_source[source]
                            for source in priority
                            if source in values_by_source
                        },
                        "selected": selected,
                    }
                )

        merged_rows.append(row)

    merged = pd.DataFrame(merged_rows, columns=["user_id", *OUTPUT_FIELDS])
    merged["user_id"] = merged["user_id"].astype("int64")
    for column in ["name", "email", "created_date", "status"]:
        merged[column] = merged[column].astype("string")

    OUT_DIR.mkdir(parents=True, exist_ok=True)
    merged.to_parquet(OUT_DIR / "merged_users.parquet", index=False)

    report = {
        "total_conflicts": len(conflicts),
        "conflicts": conflicts,
    }
    with (OUT_DIR / "conflicts.json").open("w", encoding="utf-8") as fh:
        json.dump(report, fh, indent=2, ensure_ascii=False)
        fh.write("\n")

    print(f"Wrote {len(merged)} users and {len(conflicts)} conflicts.")


if __name__ == "__main__":
    main()
EOF
